<?php
require_once __DIR__ . '/../includes/functions.php'; require_once __DIR__ . '/../includes/classes.php'; require_role(['admin','staff','cashier']); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
if($action==='create'){$pid=(int)($_POST['product_id']??0);$qty=(int)($_POST['quantity']??0);$supplier=(int)($_POST['supplier_id']??0);$notes=trim($_POST['notes']??'');if($pid<1||$qty<1)$error='Choose a product and enter a positive quantity.';else{$uid=(int)current_user()['id'];$s=$conn->prepare("INSERT INTO restock_requests(requested_by,supplier_id,status,notes) VALUES(?,NULLIF(?,0),'pending',?)");$s->bind_param('iis',$uid,$supplier,$notes);$s->execute();$rid=$conn->insert_id;$s=$conn->prepare('INSERT INTO restock_items(request_id,product_id,quantity_requested) VALUES(?,?,?)');$s->bind_param('iii',$rid,$pid,$qty);$s->execute();log_activity($conn,'CREATE','restock_requests',$rid,'Restock request submitted');flash('success','Restocking request submitted.');redirect('staff/restocking.php');}}
if($action==='approve'&&current_user()['role']==='admin'){$s=$conn->prepare("UPDATE restock_requests SET status='approved',reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status='pending'");$uid=(int)current_user()['id'];$s->bind_param('ii',$uid,$id);$s->execute();if($s->affected_rows){log_activity($conn,'APPROVE','restock_requests',$id,'Request approved');flash('success','Request approved.');}else flash('warning','Request was already processed.');redirect('staff/restocking.php');}
if($action==='reject'&&current_user()['role']==='admin'){$s=$conn->prepare("UPDATE restock_requests SET status='rejected',reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status='pending'");$uid=(int)current_user()['id'];$s->bind_param('ii',$uid,$id);$s->execute();log_activity($conn,'REJECT','restock_requests',$id,'Request rejected');flash('success','Request rejected.');redirect('staff/restocking.php');}
if($action==='receive'&&in_array(current_user()['role'],['admin','staff'],true)){$conn->begin_transaction();try{$s=$conn->prepare("SELECT id FROM restock_requests WHERE id=? AND status='approved' FOR UPDATE");$s->bind_param('i',$id);$s->execute();if(!$s->get_result()->fetch_assoc())throw new Exception('Only approved requests can be received.');$s=$conn->prepare('SELECT product_id,quantity_requested FROM restock_items WHERE request_id=?');$s->bind_param('i',$id);$s->execute();$items=$s->get_result()->fetch_all(MYSQLI_ASSOC);foreach($items as $it){$pid=(int)$it['product_id'];$qty=(int)$it['quantity_requested'];$s2=$conn->prepare('UPDATE products SET stock_quantity=stock_quantity+? WHERE id=? AND is_active=1');$s2->bind_param('ii',$qty,$pid);$s2->execute();if(!$s2->affected_rows)throw new Exception('A requested product is unavailable.');$uid=(int)current_user()['id'];$type='restock';$s2=$conn->prepare('INSERT INTO stock_movements(product_id,user_id,movement_type,quantity_change,reference_type,reference_id,notes) VALUES(?,?,?,?,?,?,?)');$ref='restock_request';$note='Received request #'.$id;$s2->bind_param('iisisis',$pid,$uid,$type,$qty,$ref,$id,$note);$s2->execute();}$s=$conn->prepare("UPDATE restock_requests SET status='received',received_at=NOW() WHERE id=? AND status='approved'");$s->bind_param('i',$id);$s->execute();log_activity($conn,'RECEIVE','restock_requests',$id,'Stock received and added');$conn->commit();flash('success','Restock received; inventory updated.');redirect('staff/restocking.php');}catch(Throwable $ex){$conn->rollback();$error=$ex->getMessage();}}
}
$products=$conn->query('SELECT id,name,product_code,stock_quantity FROM products WHERE is_active=1 ORDER BY name')->fetch_all(MYSQLI_ASSOC);$suppliers=$conn->query('SELECT id,name FROM suppliers ORDER BY name')->fetch_all(MYSQLI_ASSOC);
$historySql = 'SELECT r.*,u.name requester,s.name supplier,rv.name reviewer,GROUP_CONCAT(CONCAT(p.name, " × ",ri.quantity_requested) SEPARATOR ", ") items FROM restock_requests r JOIN users u ON u.id=r.requested_by LEFT JOIN suppliers s ON s.id=r.supplier_id LEFT JOIN users rv ON rv.id=r.reviewed_by JOIN restock_items ri ON ri.request_id=r.id JOIN products p ON p.id=ri.product_id';
if (current_user()['role'] === 'cashier') {
    $historySql .= ' WHERE r.requested_by=?';
}
$historySql .= ' GROUP BY r.id ORDER BY r.created_at DESC';
$historyStmt = $conn->prepare($historySql);
if (current_user()['role'] === 'cashier') {
    $requesterId = (int) current_user()['id'];
    $historyStmt->bind_param('i', $requesterId);
}
$historyStmt->execute();
$all = $historyStmt->get_result()->fetch_all(MYSQLI_ASSOC);
$queue=new RestockQueue();foreach($all as $r)if($r['status']==='pending')$queue->enqueue($r);
layout_header('Restocking workflow');
?>
<?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><div class="grid two section-gap"><section class="card"><h2>New restocking request</h2><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="create"><label>Product<select name="product_id" required><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>"><?= e($p['product_code'].' — '.$p['name'].' ('.$p['stock_quantity'].' in stock)') ?></option><?php endforeach; ?></select></label><label>Quantity requested<input type="number" name="quantity" min="1" required></label><label>Supplier<select name="supplier_id"><option value="0">Not specified</option><?php foreach($suppliers as $s): ?><option value="<?= $s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></label><label>Notes<input name="notes" maxlength="255"></label><button class="btn">Submit request</button></form></section><section class="card"><h2>Queue data structure</h2><p>Pending requests are loaded in oldest-first order into a FIFO queue. The oldest pending request appears first for review.</p><div class="queue-list"><?php foreach($queue->all() as $item): ?><div><b>#<?= $item['id'] ?></b> · <?= e($item['items']) ?><small><?= e($item['created_at']) ?></small></div><?php endforeach; if($queue->isEmpty()) echo '<p>No pending requests.</p>'; ?></div></section></div>
<section class="card section-gap"><h2>Request history</h2><div class="table-wrap"><table><thead><tr><th>ID/date</th><th>Requester</th><th>Items</th><th>Supplier</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($all as $r): ?><tr><td>#<?= $r['id'] ?><small><?= e($r['created_at']) ?></small></td><td><?= e($r['requester']) ?></td><td><?= e($r['items']) ?></td><td><?= e($r['supplier']??'—') ?></td><td><span class="badge"><?= e(ucfirst($r['status'])) ?></span></td><td class="actions-cell"><?php if($r['status']==='pending'&&current_user()['role']==='admin'): ?><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $r['id'] ?>"><input type="hidden" name="action" value="approve"><button class="btn btn-small btn-action btn-approve">Approve</button></form><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $r['id'] ?>"><input type="hidden" name="action" value="reject"><button class="btn btn-small btn-action btn-reject">Reject</button></form><?php elseif($r['status']==='approved'&&in_array(current_user()['role'],['admin','staff'],true)): ?><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $r['id'] ?>"><input type="hidden" name="action" value="receive"><button class="btn btn-small btn-action btn-approve">Receive stock</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php layout_footer(); ?>
